import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> dict with side, price, qty, time, active
    time_counter = 0

    for o in orders:
        if o[0] == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        typ = o[0]
        oid = o[1]
        side = o[2]
        if typ == 'market':
            qty = o[3]
            price = None
        else:
            price = o[3]
            qty = o[4]

        time_counter += 1
        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0 and sell_heap:
                neg_price, t, sid = sell_heap[0]
                if sid not in book or not book[sid]['active'] or book[sid]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                sell_price = book[sid]['price']
                if typ != 'market' and sell_price > price:
                    break
                trade_qty = min(remaining, book[sid]['qty'])
                trades.append([oid, sid, sell_price, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] == 0:
                    book[sid]['active'] = False
                    heapq.heappop(sell_heap)
                if remaining == 0:
                    break
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                             'time': time_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, time_counter, oid))
        else:
            while remaining > 0 and buy_heap:
                neg_price, t, bid = buy_heap[0]
                if bid not in book or not book[bid]['active'] or book[bid]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                buy_price = book[bid]['price']
                if typ != 'market' and buy_price < price:
                    break
                trade_qty = min(remaining, book[bid]['qty'])
                trades.append([bid, oid, buy_price, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] == 0:
                    book[bid]['active'] = False
                    heapq.heappop(buy_heap)
                if remaining == 0:
                    break
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                             'time': time_counter, 'active': True}
                heapq.heappush(sell_heap, (price, time_counter, oid))

    return trades

